$ErrorActionPreference='Stop'
. '<exact-source-03e17c31>/deploy/lan/SvLauncherInput.ps1'
$svState='<r5-state>'
$svConsole=@(Get-NetTCPConnection -LocalPort 18082 -State Listen -ErrorAction Stop)
$svWeb=@(Get-NetTCPConnection -LocalPort 3000 -State Listen -ErrorAction Stop)
$svTunnel=@(Get-NetTCPConnection -LocalPort 55448 -State Listen -ErrorAction Stop)
if ($svConsole.Count -ne 1 -or $svWeb.Count -ne 1 -or $svTunnel.Count -ne 1) {throw 'Listener count differs'}
foreach($svL in @($svConsole)+@($svWeb)+@($svTunnel)) {if($svL.LocalAddress -notin @('127.0.0.1','::1')) {throw 'Non-loopback listener'}}
$svProvider={param($svPid) (Get-CimInstance Win32_Process -Filter "ProcessId = $svPid").CommandLine}
if(-not (Test-SvOwnedByState -CommandLine (& $svProvider $svConsole[0].OwningProcess) -ScriptPath '<exact-source-03e17c31>/tools/lan_console.py' -StatePath $svState)) {throw 'Console state ownership differs'}
$svTokens=@(Get-SvArgv (& $svProvider $svWeb[0].OwningProcess))
if(-not @($svTokens | Where-Object {Test-SvSamePath $_ '<exact-source-03e17c31>/apps/web/node_modules/vite/bin/vite.js'}).Count) {throw 'Web source ownership differs'}
if(-not(Assert-SvOwnedTunnelListeners -Listeners $svTunnel -ExpectedForward '127.0.0.1:55448:127.0.0.1:55448' -ExpectedTarget '<host-1>' -CommandLineProvider $svProvider -ExpectedProcessId 35844)) {throw 'Tunnel ownership differs'}
@{loopbackOnly=$true;consoleStateOwned=$true;webSourceOwned=$true;tunnelOwned=$true;listenersPerPort=1} | ConvertTo-Json -Compress

